import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {useCallback, useState} from 'react'

import {useMyUsername} from '../../../../../hooks/useMyUsername'
import {extractErrorMessage} from '../../../../../utils/extractError'
import {twoFactorAuthApi} from '../../TwoFactorAuthPages.rest'
import RecoveryKeysDialog from '../RecoveryKeysDialog/RecoveryKeysDialog'

import styles from './ConfigurationForm.module.css'

function NewRecoveryKeysButton() {
  const [recoveryKeysVisible, setRecoveryKeysVisible] = useState(false)
  const [requestNewRecoveryKeys, {loading, error, recoveryKeys}] =
    twoFactorAuthApi.endpoints.generateRecoveryKeys.useMutation({
      selectFromResult: ({isLoading, data, error}) => ({
        loading: isLoading,
        error,
        recoveryKeys: data?.recoveryKeys,
      }),
    })
  const onClick = useCallback(async () => {
    await requestNewRecoveryKeys()
    setRecoveryKeysVisible(true)
  }, [requestNewRecoveryKeys])
  return (
    <>
      <Button onClick={onClick} className={styles.delete} loader={loading}>
        {'Generate new recovery keys...'}
      </Button>
      {!loading && error && (
        <span className={styles.error}>{'Couldn’t generate codes. Please try again later.'}</span>
      )}
      {recoveryKeys && (
        <RecoveryKeysDialog
          recoveryKeys={recoveryKeys}
          show={recoveryKeysVisible}
          onClose={() => setRecoveryKeysVisible(false)}
        />
      )}
    </>
  )
}

type DisableButtonProps = {
  disabled?: boolean
}

function DisableButton({disabled}: DisableButtonProps) {
  const username = useMyUsername()
  const [requestDisable2FA] = twoFactorAuthApi.endpoints.disable2FA.useMutation()
  const onClick = useCallback(async () => {
    if (username == null) {
      // never happens, because the button is disabled at this condition, so click is impossible
      return
    }
    const result = await requestDisable2FA(username)
    if ('error' in result) {
      alertService.error(extractErrorMessage(result.error))
    } else {
      location.reload()
    }
  }, [requestDisable2FA, username])
  const button = (
    <Button
      onClick={onClick}
      className={styles.delete}
      loader={username == null}
      disabled={disabled}
    >
      {'Disable'}
    </Button>
  )
  return disabled ? (
    <Dropdown anchor={button} hoverMode>
      <Popup className={styles.popup}>
        {'Two-Factor Authentication is mandatory on this server'}
      </Popup>
    </Dropdown>
  ) : (
    button
  )
}

type Props = {
  canDisable2FA: boolean
}

function ConfigurationForm({canDisable2FA}: Props) {
  return (
    <div className={styles.configurationForm}>
      <h2 className={styles.greenHeading}>{'Authentication is Enabled'}</h2>
      <DisableButton disabled={!canDisable2FA} />
      <h2 className={styles.heading}>{'Recovery Codes'}</h2>
      <div>
        {'In case you lose access to your authenticator app,'}
        <br />
        {'you can use disposable recovery codes to sign in to your TeamCity account.'}
      </div>
      <NewRecoveryKeysButton />
    </div>
  )
}

export default ConfigurationForm
