import {Suspense} from 'react'

import Loader from '../../../common/Loader/Loader'

import ConfigurationForm from './ConfigurationForm/ConfigurationForm'
import SetupForm from './SetupForm/SetupForm.container'

type Props = {
  hasActive2FA: boolean
  canDisable2FA: boolean
}

function TwoFactorAuthSettingsPage({hasActive2FA, canDisable2FA}: Props) {
  return hasActive2FA ? (
    <ConfigurationForm canDisable2FA={canDisable2FA} />
  ) : (
    <Suspense fallback={<Loader />}>
      <SetupForm />
    </Suspense>
  )
}

export default TwoFactorAuthSettingsPage
