import {useContext} from 'react'
import {graphql, useFragment} from 'react-relay'

import {CurrentUserKeyContext} from '../contexts/currentUserKey'

import type {useMyUsernameFragment$key} from './__generated__/useMyUsernameFragment.graphql'

const useMyUsernameFragment = graphql`
  fragment useMyUsernameFragment on User {
    username
  }
`

export function useMyUsername() {
  const currentUserKey = useContext(CurrentUserKeyContext)
  const {username} =
    useFragment<useMyUsernameFragment$key>(useMyUsernameFragment, currentUserKey) ?? {}
  return username
}
