import Button from '@jetbrains/ring-ui-built/components/button/button'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import {useCallback, useState} from 'react'
import type * as React from 'react'
import QRCode from 'react-qr-code'

import {extractErrorMessage} from '../../../../../utils/extractError'
import {resolveHelpURL} from '../../../../../utils/url'
import HelpLink from '../../../../common/HelpLink/HelpLink'
import type {SetupResponse} from '../../TwoFactorAuthPages.rest'
import {twoFactorAuthApi} from '../../TwoFactorAuthPages.rest'
import RecoveryKeysDialog from '../RecoveryKeysDialog/RecoveryKeysDialog'

import styles from './SetupForm.module.css'

function otpAuthLink(secretKey: string, username: string) {
  return `otpauth://totp/${username}?secret=${secretKey}&issuer=TeamCity`
}

function toHumanReadable(secretKey: string) {
  const blockSize = 4
  const blocks = []
  for (let blockStart = 0; blockStart < secretKey.length; blockStart += blockSize) {
    blocks.push(secretKey.substr(blockStart, blockSize))
  }
  return blocks.join(' ')
}

type SecretKeyRepresentationsProps = {
  secretKey: string
  username: string
}

function SecretKeyRepresentations(props: SecretKeyRepresentationsProps) {
  return (
    <div className={styles.keyRepresentations}>
      <div>
        {'Scan this QR code with the authenticator app:'}
        <div className={styles.qrWrapper}>
          <QRCode
            value={otpAuthLink(props.secretKey, props.username)}
            className={styles.qr}
            bgColor="var(--ring-content-background-color)"
            fgColor="transparent"
            size={264}
          />
        </div>
      </div>
      <div>
        {'If your app doesn’t recognize the QR code,'}
        <br />
        {'enter this key manually:'}
        <br />
        <b>{toHumanReadable(props.secretKey)}</b>
      </div>
    </div>
  )
}

type ConfirmationFormProps = {
  recoveryKeys: string[]
  uuid: string
}

function ConfirmationForm({recoveryKeys, uuid}: ConfirmationFormProps) {
  const [password, setPassword] = useState('')
  const [requestConfirmation, {loading, error}] = twoFactorAuthApi.endpoints.confirm.useMutation({
    selectFromResult: ({isLoading, error}) => ({loading: isLoading, error}),
  })
  const [recoveryKeysVisible, setRecoveryKeysVisible] = useState(false)
  const onSubmit = useCallback(
    async (event: React.SyntheticEvent) => {
      event?.preventDefault()
      const result = await requestConfirmation({uuid, password: parseInt(password, 10)})
      if (!('error' in result)) {
        setRecoveryKeysVisible(true)
      }
    },
    [requestConfirmation, uuid, password],
  )
  return (
    <form onSubmit={onSubmit}>
      <Input
        size={Size.AUTO}
        className={styles.password}
        inputClassName={styles.passwordInner}
        label="Enter the code generated by the app"
        type="number"
        value={password}
        autoComplete="off"
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPassword(e.target.value)}
      />
      <Button primary loader={loading} type="submit">
        {'Confirm'}
      </Button>
      {!loading && error && (
        <span className={styles.error}>
          {'status' in error && error.status === HTTPCodesEnum.BAD_REQUEST
            ? 'Incorrect password'
            : extractErrorMessage(error)}
        </span>
      )}
      {recoveryKeys && (
        <RecoveryKeysDialog
          recoveryKeys={recoveryKeys}
          show={recoveryKeysVisible}
          onClose={() => {
            setRecoveryKeysVisible(false)
            location.reload()
          }}
        />
      )}
    </form>
  )
}

type Props = SetupResponse & {
  username: string
}

function SetupForm({secretKey, recoveryKeys, uuid, username}: Props) {
  return (
    <div>
      {'To enable 2FA, you will need a mobile device with an authenticator app installed.'}
      <HelpLink
        className={styles.helpIcon}
        url={resolveHelpURL(
          'configuring-your-user-profile.html#Configuring+Two-Factor+Authentication',
        )}
        Component={IconButton}
        icon="help"
        preservePlus
      />
      <SecretKeyRepresentations secretKey={secretKey} username={username} />
      <ConfirmationForm recoveryKeys={recoveryKeys} uuid={uuid} />
    </div>
  )
}

export default SetupForm
