import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useCallback} from 'react'

import {downloadFile} from '../../../../../utils/download'
import CopyIconButton from '../../../../common/CopyIconButton/CopyIconButton'

import styles from './RecoveryKeysDialog.module.css'

type Props = {
  recoveryKeys: string[]
  show: boolean
  onClose: () => void
}

function RecoveryKeysDialog({recoveryKeys, show, onClose}: Props) {
  const recoveryKeysInText = recoveryKeys.join('\n')
  const download = useCallback(() => {
    downloadFile(recoveryKeysInText, 'teamcity-recovery-codes.txt', 'text/plain')
  }, [recoveryKeysInText])
  return (
    <Dialog show={show}>
      <Header>{'Save recovery codes'}</Header>
      <Content>
        {
          'In case you lose access to your authenticator app, you can use these disposable recovery codes to sign in to your TeamCity account:'
        }
        <div className={styles.recoveryKeysWithActions}>
          <div className={styles.recoveryKeys}>{recoveryKeysInText}</div>
          <div className={styles.actions}>
            <CopyIconButton
              text={recoveryKeysInText}
              title={'Copy recovery codes to clipboard'}
              beforeCopyContent={'Copy to clipboard'}
              afterCopyContent={'Copied to clipboard'}
            />
            <IconButton icon="download" title={'Download recovery codes'} onClick={download}>
              {'Download'}
            </IconButton>
          </div>
        </div>
        <strong>
          {
            'These codes are displayed only once! Make sure you store them in a safe place before closing this dialog.'
          }
        </strong>
      </Content>
      <Panel>
        <Button onClick={onClose}>{'I have saved the codes'}</Button>
      </Panel>
    </Dialog>
  )
}

export default RecoveryKeysDialog
