import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {useCallback, useEffect, useMemo} from 'react'

import {useMyUsername} from '../../../../../hooks/useMyUsername'
import {usePermission} from '../../../../../hooks/usePermission'
import {Permission, ROOT_PROJECT_ID} from '../../../../../types'
import {extractErrorMessage} from '../../../../../utils/extractError'
import Loader from '../../../../common/Loader/Loader'
import {twoFactorAuthApi} from '../../TwoFactorAuthPages.rest'

import SetupForm from './SetupForm'

import styles from './SetupForm.module.css'

function useSecretKeyAndRecoveryKeys() {
  const [requestSetup2FA, {loading, error, keys}] = twoFactorAuthApi.endpoints.setup2FA.useMutation(
    {
      selectFromResult: ({isLoading, error, data}) => ({loading: isLoading, error, keys: data}),
    },
  )
  const fetch = useCallback(() => requestSetup2FA(), [requestSetup2FA])
  return {keys, loading, error, fetch}
}

function SetupFormContainer() {
  const canEditOwnProfile = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const username = useMyUsername()
  const {keys, loading, error, fetch} = useSecretKeyAndRecoveryKeys()
  useEffect(() => {
    fetch()
  }, [fetch])
  useMemo(() => {
    if (error && canEditOwnProfile) {
      alertService.error(extractErrorMessage(error))
    }
  }, [error, canEditOwnProfile])
  if (loading || username == null) {
    return <Loader />
  }
  if (!canEditOwnProfile) {
    return <div>{'Two-Factor authentication is disabled'}</div>
  }
  if (error || keys == null) {
    return (
      <div className={styles.error}>
        {'Couldn’t load the tab. '}
        <Link onClick={fetch}>{'Try again'}</Link>
      </div>
    )
  }
  return <SetupForm {...keys} username={username} />
}

export default SetupFormContainer
